      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (terms, end date, pricing, renewal clauses), any internal pricing/renewal policy documents, SLA terms, and recent invoices; run the SLA credit calculator against logged performance/incident data to determine any SLA misses and credits owed; if any amounts are in USD or another foreign currency, use the currency converter to express them in our reporting currency.",
      "why": "The executor needs the exact contract terms, policy constraints, SLA performance/credit facts, and correctly converted amounts before a renewal counter-offer can be drafted."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the vendor-facing reply to Acme Cloud Services acknowledging the contract end date, addressing the proposed 12% price increase and 12-month renewal (accepting, countering, or requesting justification per policy findings), and including any SLA credits owed to us based on the retrieved facts.",
      "why": "The executor turns the gathered contract, policy, and SLA facts into the final reply for human review and approval."
    }
